  ('nashville-tax-soltuions-paras', 'alexandra', 'thank you', NULL, NULL, NULL, NULL, '2025-08-08T18:18:00+00:00'),
  ('nashville-tax-soltuions-paras', 'U096WS8LT3Q', 'No problem', NULL, NULL, NULL, NULL, '2025-08-08T18:18:39+00:00'),
  ('nashville-tax-soltuions-paras', 'alexandra', 'Hey Jace Camille is having me reach out to some of her clients and in the notes for the Denko''s she stated that you and her would both need to be available is there anytime that doesn''t work in the next week or so for you or a better time?', NULL, NULL, NULL, NULL, '2025-08-20T19:31:58+00:00'),
  ('nashville-tax-soltuions-paras', 'U096WS8LT3Q', 'Nothing Tuesday, and nothing Wednesday afternoon please. Anything else should be fine', NULL, NULL, NULL, NULL, '2025-08-20T20:01:42+00:00'),
  ('nashville-tax-soltuions-paras', 'alexandra', 'ok thank you', NULL, NULL, NULL, NULL, '2025-08-20T20:02:05+00:00'),
  ('nashville-tax-soltuions-paras', 'U096WS8LT3Q', 'You are welcome', NULL, NULL, NULL, NULL, '2025-08-20T20:02:22+00:00'),
