  ('nashville-tax-soltuions-paras', 'U096WS8LT3Q', 'On what day?', NULL, NULL, NULL, NULL, '2025-08-20T20:12:37+00:00'),
  ('nashville-tax-soltuions-paras', 'alexandra', 'Monday the 25th', NULL, NULL, NULL, NULL, '2025-08-20T20:16:38+00:00'),
