  ('nashville-tax-soltuions-paras', 'Averie', 'Hey Jace, I''m making an individual Alabama POA. I was just wondering if the tax types are Income, Civil Penalties, and Health Care Penalty?', NULL, NULL, NULL, NULL, '2025-09-17T15:41:36+00:00'),
  ('nashville-tax-soltuions-paras', 'U096WS8LT3Q', 'No health care but everything else', NULL, NULL, NULL, NULL, '2025-09-17T15:51:19+00:00'),
  ('nashville-tax-soltuions-paras', 'Averie', 'Okay thank you', NULL, NULL, NULL, NULL, '2025-09-17T16:03:40+00:00'),
  ('nashville-tax-soltuions-paras', 'Averie', 'is the form number for income 1040 then?', NULL, NULL, NULL, NULL, '2025-09-17T16:08:55+00:00'),
