  ('nashvilletaxsolutions-training-associates', 'Camille Loose', 'Shuck N Ale is missing stuff too', NULL, NULL, NULL, NULL, '2025-07-28T19:21:28+00:00'),
  ('nashvilletaxsolutions-training-associates', 'U096WS8LT3Q', 'Yeah, But Shuck n Ale we can resolve without. We are shutting it down. Worse case scenario, we can get some time to do so.', NULL, NULL, NULL, NULL, '2025-07-28T19:22:00+00:00'),
